/* Database load, round two (round rel2-db, run after 334). Indexes for the foreign keys a delete or a join walks with no index to follow, each found unindexed on a database built from every part: deleting an account (lib/account/delete-account.ts, and the spam purge through it, deletes the sign in account of an account with nothing sold, and Postgres then searched every table that names that account: library items, comments, poll votes, points, activity days and hours, conversations, invites used, badges, join answers, onboarding, library activity and purchases, chat deliveries, leave reasons, cancellations, contact messages, handles kept, template purchases, contacts, the activity log, site versions), deleting a store (entitlements, theme history and reports, flow jobs, membership posts, review drafts and uploads, blog revisions, stock holds), a website (store_theme_installs and its copies, theme history and reports, a site's forms, collection items, form submissions, deployments, agent runs and chat by version and run), a bulk product delete with its variants, courses and lessons (flow log, notifications about a listing, review drafts, fulfilment links, library purchases, bundles, transfer lines, course progress and enrolments, the last lesson), refunds by order and by entitlement, notifications by conversation, a OnePage's lead magnets, old addresses and gifted downloads, a chat message pinned in a space (community_spaces.pinned_message_id: every message deleted searched every space), a community's bookmarks, polls, RSVPs, access, chat members and preferences, members by tier, and the location, shipping profile and package an order, a product, a variant, a stock movement, a hold, a fulfilment, a return, a transfer or a checkout points at. A nullable column is indexed only where it is set (WHERE col IS NOT NULL), which is every row a delete looks for. Left out on purpose: tables of a few rows per store or community (shipping zones and rates, commerce and store settings, chat, library, join form, onboarding and email template settings, sales channels, tiers' invites, scheduled posts, the who changed it columns such as updated_by and invited_by), where a search is as fast as an index and the index is one more thing to write; and tables written on every visit and read only in bulk (product_views, site_rum_events, site_rum_counters, site_rum_daily, site_web_vitals, activity_push_queue, ai_site_job_events), where an index would cost every page view or job step to save a rare delete. Then one grouped read for a community's spaces: public.community_space_counts(community) gives each space's feed posts and a chat space's messages in one query, where the admin asked two exact counts per space; SECURITY INVOKER, callable by the service role only. Last, grants nobody uses closed: cleanup_expired_auth_codes() (it deletes codes with its owner's rights) is the service role's, no longer the public key's, and the INSERT policies open to anybody on auth_recovery_requests, onepage_leads, product_views and blog_post_views are dropped: every write to them goes through the service role (app/api/onepage, app/api/blog/track, lib/onepage/signup-server.ts, the counters in lib/analytics/collect.ts); the owners' own read, update and delete policies stay, and onepage_views and onepage_clicks keep theirs (app/api/onepage/track writes them with the visitor's client). No row changes. LOCKS: a plain CREATE INDEX stops writes to its table while it builds and the editor holds that to the end of the paste: on a large database run supabase/sql/RUN_REL2_DB_INDEXES_CONCURRENTLY.sql first, line by line, and this part then finds every index made. Each index is made only when its table and column are there and no index led by that column is. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.library_items') IS NULL THEN RAISE NOTICE 'part 443: library_items_user_id_idx skipped, public.library_items does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'library_items' AND column_name = 'user_id') THEN RAISE NOTICE 'part 443: library_items_user_id_idx skipped, public.library_items lacks a column it needs'; RETURN; END IF; IF to_regclass('public.library_items_user_id_idx') IS NOT NULL THEN RETURN; END IF; IF EXISTS (SELECT 1 FROM pg_index i JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0] WHERE i.indrelid = 'public.library_items'::regclass AND a.attname = 'user_id' AND i.indisvalid AND (i.indpred IS NULL OR pg_get_expr(i.indpred, i.indrelid) = '(user_id IS NOT NULL)')) THEN RAISE NOTICE 'part 443: library_items_user_id_idx skipped, public.library_items already has an index led by user_id'; RETURN; END IF; CREATE INDEX IF NOT EXISTS library_items_user_id_idx ON public.library_items (user_id); END $do$;
