DO $do$ BEGIN IF to_regclass('public.community_spaces') IS NULL OR to_regclass('public.community_feed_posts') IS NULL OR to_regclass('public.community_messages') IS NULL THEN RAISE NOTICE 'part 443: community_space_counts skipped, the community tables are not here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_spaces' AND column_name = 'community_id') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_spaces' AND column_name = 'kind') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_feed_posts' AND column_name = 'space_id') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_messages' AND column_name = 'space_id') THEN RAISE NOTICE 'part 443: community_space_counts skipped, a community table lacks a column it needs'; RETURN; END IF; EXECUTE $fn$CREATE OR REPLACE FUNCTION public.community_space_counts(p_community_id uuid) RETURNS TABLE (space_id uuid, posts bigint, messages bigint) LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public, pg_temp AS $body$ SELECT s.id, coalesce(p.n, 0)::bigint, coalesce(m.n, 0)::bigint FROM public.community_spaces s LEFT JOIN (SELECT fp.space_id AS sid, count(*) AS n FROM public.community_feed_posts fp WHERE fp.space_id IN (SELECT x.id FROM public.community_spaces x WHERE x.community_id = p_community_id) GROUP BY fp.space_id) p ON p.sid = s.id LEFT JOIN (SELECT cm.space_id AS sid, count(*) AS n FROM public.community_messages cm WHERE cm.space_id IN (SELECT x.id FROM public.community_spaces x WHERE x.community_id = p_community_id AND x.kind = 'chat') GROUP BY cm.space_id) m ON m.sid = s.id WHERE s.community_id = p_community_id $body$$fn$; REVOKE ALL ON FUNCTION public.community_space_counts(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.community_space_counts(uuid) TO service_role; END $do$;
