DO $do$ DECLARE r record; BEGIN IF to_regclass('public.auth_recovery_requests') IS NULL THEN RETURN; END IF; ALTER TABLE public.auth_recovery_requests ENABLE ROW LEVEL SECURITY; FOR r IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'auth_recovery_requests' AND cmd = 'INSERT' AND coalesce(with_check, 'true') = 'true' AND roles && ARRAY['public', 'anon', 'authenticated']::name[] LOOP EXECUTE format('DROP POLICY IF EXISTS %I ON public.auth_recovery_requests', r.policyname); END LOOP; END $do$;
